import pandas as pd
import numpy as np
import json

DATA_FILE = "/home/chs/Work/tga_plot/eval/inputs_b/caox.csv"

def main():
    # Read the CSV file
    df = pd.read_csv(DATA_FILE)

    # Extract columns based on header names
    temp_col = "Temperature (°C)"
    weight_col = "Weight (%)"
    dtg_col = "Deriv. Weight (%/°C)"

    # Get data arrays
    temperature = df[temp_col].values
    weight = df[weight_col].values
    dtg = df[dtg_col].values

    # Calculate DTG inverted for display (peaks point up)
    dtg_inverted = -dtg

    # Find residue at 800°C (nearest measured point)
    idx_800 = np.argmin(np.abs(temperature - 800))
    residue_weight = weight[idx_800]
    residue_temp = temperature[idx_800]

    # Find highest DTG peak above 150°C
    mask_above_150 = temperature > 150
    if np.any(mask_above_150):
        dtg_for_peak = dtg.copy()
        dtg_for_peak[~mask_above_150] = 0  # Set values below 150 to 0 so they don't affect max
        # We want the most negative DTG value (which becomes the highest positive after inversion)
        min_dtg_idx = np.argmin(dtg_for_peak)
        peak_temp = temperature[min_dtg_idx]
        peak_dtg_value = dtg[min_dtg_idx]
    else:
        peak_temp = None
        peak_dtg_value = None

    # Prepare data for ECharts
    # For line charts, we need [x, y] pairs
    weight_data = [[float(t), float(w)] for t, w in zip(temperature, weight)]
    dtg_data = [[float(t), float(d)] for t, d in zip(temperature, dtg_inverted)]

    # Residue marker data
    residue_marker = [[float(residue_temp), float(residue_weight)]]

    # Peak marker data
    if peak_temp is not None:
        peak_marker = [[float(peak_temp), float(-peak_dtg_value)]]  # Inverted for display
    else:
        peak_marker = []

    # Build the two separate plots stacked vertically using grid
    option = {
        "title": [
            {
                "text": "Weight (%)",
                "left": "center",
                "top": "2%",
                "textStyle": {
                    "fontSize": 14,
                    "fontFamily": "Noto Sans CJK KR"
                }
            },
            {
                "text": "DTG (%/°C)",
                "left": "center",
                "bottom": "2%",
                "textStyle": {
                    "fontSize": 14,
                    "fontFamily": "Noto Sans CJK KR"
                }
            }
        ],
        "grid": [
            {
                "id": "grid_top",
                "left": "10%",
                "right": "10%",
                "top": "10%",
                "height": "35%"
            },
            {
                "id": "grid_bottom",
                "left": "10%",
                "right": "10%",
                "top": "60%",
                "height": "35%"
            }
        ],
        "xAxis": [
            {
                "type": "value",
                "name": "Temperature (°C)",
                "nameLocation": "middle",
                "nameGap": 30,
                "gridIndex": 0,
                "axisLabel": {"show": False},
                "splitLine": {"show": True, "lineStyle": {"color": "#eee"}},
                "axisLine": {"lineStyle": {"color": "#333"}}
            },
            {
                "type": "value",
                "name": "Temperature (°C)",
                "nameLocation": "middle",
                "nameGap": 30,
                "gridIndex": 1,
                "axisLabel": {"show": True, "fontSize": 10},
                "splitLine": {"show": True, "lineStyle": {"color": "#eee"}},
                "axisLine": {"lineStyle": {"color": "#333"}}
            }
        ],
        "yAxis": [
            {
                "type": "value",
                "name": "Weight (%)",
                "nameLocation": "middle",
                "nameGap": 40,
                "gridIndex": 0,
                "position": "left",
                "axisLabel": {"fontSize": 10},
                "splitLine": {"show": True, "lineStyle": {"color": "#eee"}},
                "axisLine": {"lineStyle": {"color": "#333"}}
            },
            {
                "type": "value",
                "name": "DTG (%/°C)",
                "nameLocation": "middle",
                "nameGap": 40,
                "gridIndex": 1,
                "position": "left",
                "axisLabel": {"fontSize": 10},
                "splitLine": {"show": True, "lineStyle": {"color": "#eee"}},
                "axisLine": {"lineStyle": {"color": "#333"}}
            }
        ],
        "series": [
            {
                "name": "Weight",
                "type": "line",
                "data": weight_data,
                "xAxisIndex": 0,
                "yAxisIndex": 0,
                "smooth": False,
                "symbol": "none",
                "lineStyle": {
                    "width": 2,
                    "color": "#1f4e9c"
                },
                "markPoint": {
                    "data": [
                        {
                            "coord": [float(residue_temp), float(residue_weight)],
                            "value": f"Residue {residue_weight:.1f}%",
                            "symbolSize": 10,
                            "itemStyle": {
                                "color": "#1f4e9c"
                            },
                            "label": {
                                "show": True,
                                "formatter": "{b}",
                                "position": "right",
                                "fontSize": 11,
                                "color": "#1f4e9c"
                            }
                        }
                    ]
                }
            },
            {
                "name": "DTG",
                "type": "line",
                "data": dtg_data,
                "xAxisIndex": 1,
                "yAxisIndex": 1,
                "smooth": False,
                "symbol": "none",
                "lineStyle": {
                    "width": 2,
                    "color": "#c0392b"
                },
                "markPoint": {
                    "data": [
                        {
                            "coord": [float(peak_temp), float(-peak_dtg_value)],
                            "value": f"{peak_temp:.0f} °C",
                            "symbolSize": 10,
                            "itemStyle": {
                                "color": "#c0392b"
                            },
                            "label": {
                                "show": True,
                                "formatter": "{b}",
                                "position": "top",
                                "fontSize": 11,
                                "color": "#c0392b"
                            }
                        }
                    ] if peak_temp is not None else []
                }
            }
        ]
    }

    result = {
        "figures": [
            {
                "name": "plot1",
                "option": option,
                "width": 614,
                "height": 442,
                "dpi": 300,
                "formats": ["png"]
            }
        ]
    }

    print(json.dumps(result, ensure_ascii=False))

if __name__ == "__main__":
    main()
